import Hashids from "hashids";

const hashids = new Hashids("4ceps-secret-key", 8);

export const safeEncodeHex = (idOrObj) => {
  if (!idOrObj) return "";
  try {
    const idStr = typeof idOrObj === "object" ? (idOrObj._id || idOrObj).toString() : idOrObj.toString();
    if (!/^[0-9a-fA-F]{24}$/.test(idStr)) {
      return "";
    }
    return hashids.encodeHex(idStr);
  } catch (e) {
    console.error("Error encoding hex with Hashids:", e);
    return "";
  }
};

hashids.safeEncodeHex = safeEncodeHex;

export default hashids;