import { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { useCart } from "./CartContext";
import axios from "axios";
import moment from "moment";
import { getTodayDate, isFutureOrToday } from "../utils/timeAgo";
import hashids from "../utils/hashids";
import {
  FaArrowLeft,
  FaArrowRight,
  FaTrashAlt,
  FaCalendarAlt,
  FaClock,
  FaShoppingCart,
  FaCheckCircle,
  FaInfoCircle,
} from "react-icons/fa";
import UnifiedAuthModal from "./UnifiedAuthModal";
import { toast } from "react-hot-toast";

const Cart = () => {
  const { cartItems, removeFromCart } = useCart();

  const [appointmentData, setAppointmentData] = useState({});
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();
  const previousPage = location.state?.from || "/";

  // ✅ Load appointmentData from localStorage when component mounts
  useEffect(() => {
    const savedData = localStorage.getItem("appointmentDetails");
    if (savedData) {
      setAppointmentData(JSON.parse(savedData));
    }
  }, []);

  // ✅ Update localStorage whenever appointmentData changes
  useEffect(() => {
    localStorage.setItem("appointmentDetails", JSON.stringify(appointmentData));
  }, [appointmentData]);

  const handleRemove = (item) => {
    const id =
      item?.type === "service" ? item?.service?._id : item?.package?._id;

    // Remove from cart
    removeFromCart(id, item?.type);

    // Also remove from appointmentData
    const updated = { ...appointmentData };
    delete updated[id];
    setAppointmentData(updated);
  };

  const handleDateChange = (id, date) => {
    setAppointmentData((prev) => ({
      ...prev,
      [id]: {
        ...prev[id],
        date,
        time: "",
      },
    }));
  };

  useEffect(() => {
    const clearOnRefresh = () => {
      localStorage.removeItem("appointmentDetails");
    };

    window.addEventListener("beforeunload", clearOnRefresh);
    return () => {
      window.removeEventListener("beforeunload", clearOnRefresh);
    };
  }, []);

  const handleTimeChange = (id, time) => {
    const selectedDate = appointmentData[id]?.date || null;

    setAppointmentData((prev) => ({
      ...prev,
      [id]: {
        ...(prev[id] || {}),
        time,
      },
    }));
  };

  const handleNextClick = () => {
    if (cartItems.length === 0) {
      // alert("Please select at least one booking to proceed forward");
      toast.error("Please select at least one service or package to proceed forward");
      return;
    }
    let isValid = true;

    cartItems.forEach((item) => {
      const id =
        item.type === "service" ? item.service?._id : item.package?._id;
      const appt = appointmentData[id] || {};
      if (!appt.date || !appt.time) {
        isValid = false;
      }
    });

    if (!isValid) {
      // alert(
      //   "Please select both date and time for all items before proceeding."
      // );
      toast.error(
        "Please select both date and time for all items before proceeding.",
        {
          autoClose: 5000,
        },
      );
      return;
    }

    const isLoggedIn =
      localStorage.getItem("userToken") || localStorage.getItem("token");
    if (isLoggedIn) {
      navigate("/cart-personal");
    } else {
      setIsAuthModalOpen(true);
    }
  };

  // Fetching data & time from backend for service & package
  const [serviceSlots, setServiceSlots] = useState({});

  const fetchItemsofCart = async (id, type) => {
    if (!id || !type) {
      console.error("Missing id or type");
      return;
    }

    try {
      let url = "";
      if (type === "service") {
        url = `${process.env.REACT_APP_BACKEND_URL}/api/centreService/decrypted/${hashids.safeEncodeHex(id)}`;
      } else if (type === "package") {
        url = `${process.env.REACT_APP_BACKEND_URL}/api/packages/single/${id}`;
      } else {
        console.error("Invalid type:", type);
        return;
      }

      const res = await axios.get(url);

      const slotsData =
        type === "service"
          ? res.data?.service?.slots
          : res.data?.package?.slots;

      setServiceSlots((prev) => ({ ...prev, [id]: slotsData || [] }));
      return res.data;
    } catch (err) {
      console.error("Error fetching item from cart:", err);
    }
  };

  function formatTime24To12(time24) {
    if (
      time24.toUpperCase().includes("AM") ||
      time24.toUpperCase().includes("PM")
    ) {
      return time24.replace(/\s+/g, "");
    }
    const [hourStr, minute] = time24.split(":");
    let hour = parseInt(hourStr, 10);
    const ampm = hour >= 12 ? "PM" : "AM";
    hour = hour % 12 || 12;
    return `${hour}:${minute}${ampm}`;
  }

  function formatSlot(slot) {
    if (typeof slot === "string") {
      const [from, to] = slot.split("-");
      return `${formatTime24To12(from)}-${formatTime24To12(to)}`;
    } else if (slot?.from && slot?.to) {
      return `${formatTime24To12(slot.from)}-${formatTime24To12(slot.to)}`;
    } else {
      return String(slot);
    }
  }

  function getDayName(dateString) {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", { weekday: "long" });
  }

  useEffect(() => {
    cartItems.forEach((item) => {
      const isService = item.type === "service";
      const id = isService ? item.service?._id : item.package?._id;
      if (id) {
        fetchItemsofCart(id, item.type);
      }
    });
  }, [cartItems]);

  function isSlotAvailable(slot, selectedDate) {
    if (!selectedDate) return true;

    let fromTimeStr = "";
    if (typeof slot === "string") {
      fromTimeStr = slot.split("-")[0];
    } else if (slot.from) {
      fromTimeStr = slot.from;
    } else {
      return true;
    }

    const slotTime = moment(
      `${selectedDate} ${fromTimeStr}`,
      "YYYY-MM-DD hh:mm A",
    );

    if (moment(selectedDate, "YYYY-MM-DD").isSame(moment(), "day")) {
      return slotTime.isAfter(moment().add(2, "hours"));
    }

    return true;
  }

  const toTitleCase = (str) => {
    return str
      .toLowerCase()
      .split(" ")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(" ");
  };

  const createSlug = (text) => {
    if (!text) return "";
    return text
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^_|_$/g, "");
  };
  const totalPrice = cartItems.reduce((acc, item) => {
    const data = item.type === "service" ? item.service : item.package;
    return acc + (data?.totalPrice || 0);
  }, 0);

  return (
    <div className="cart-page-modern padding-y-120">
      <div className="container">
        {/* Checkout Progress Indicator */}
        <div className="checkout-progress-wrapper mb-5">
          <div className="checkout-progress d-flex justify-content-between align-items-center position-relative">
            <div className="progress-line position-absolute w-100 top-50 start-0 translate-middle-y z-index--1"></div>
            <div className="progress-step active">
              <div className="step-count shadow-sm">
                <FaShoppingCart />
              </div>
              <span className="step-label">My Cart</span>
            </div>
            <div className="progress-step">
              <div className="step-count shadow-sm">2</div>
              <span className="step-label">Personal Details</span>
            </div>
            <div className="progress-step">
              <div className="step-count shadow-sm">
                <FaCheckCircle />
              </div>
              <span className="step-label">Confirmation</span>
            </div>
          </div>
        </div>

        <div className="row gy-4 gx-lg-5" style={{ marginTop: "-20px" }}>
          {/* Left Column: Cart Items */}
          <div className="col-lg-8">
            <div className="cart-items-header d-flex justify-content-between align-items-center mb-4">
              <h4 className="fw-700 mb-0">
                Shopping Cart{" "}
                <span className="text-muted font-18 fw-400">
                  ({cartItems.length} items)
                </span>
              </h4>
              <p className="text-main mb-0 font-14 fw-600">
                <FaInfoCircle className="me-1" /> Slots must be 2+ hours from
                now
              </p>
            </div>

            <div className="cart-items-list d-flex flex-column gap-4">
              {cartItems.length === 0 ? (
                <div className="empty-cart-state text-center py-5 glass-effect rounded-4">
                  <div className="empty-icon-wrap mb-3">
                    <FaShoppingCart
                      size={60}
                      className="text-muted opacity-25"
                    />
                  </div>
                  <h5 className="fw-700">Your cart is empty</h5>
                  <p className="text-muted mb-4">
                    Looks like you haven't added any bookings yet.
                  </p>
                  <Link to={previousPage} className="btn btn-main pill px-5">
                    Continue Booking
                  </Link>
                </div>
              ) : (
                cartItems.map((item, index) => {
                  const isService = item.type === "service";
                  const data = isService ? item.service : item.package;
                  const itemId = data?._id;
                  const selectedDate = appointmentData[itemId]?.date;
                  const selectedDay = selectedDate
                    ? getDayName(selectedDate)
                    : null;
                  const allSlots = serviceSlots[itemId] || [];

                  let filteredSlots = selectedDay
                    ? allSlots.filter(
                        (s) =>
                          s.day.trim().toLowerCase() ===
                          selectedDay.toLowerCase(),
                      )
                    : [];

                  filteredSlots = filteredSlots.filter((s) =>
                    isSlotAvailable(s, selectedDate),
                  );
                  filteredSlots.sort(
                    (a, b) =>
                      moment(a.from, "hh:mm A") - moment(b.from, "hh:mm A"),
                  );
                  const noSlotsForDay =
                    selectedDate && filteredSlots.length === 0;

                  return (
                    <div
                      key={item._id || index}
                      className="cart-item-card glass-effect p-4 p-md-4 rounded-4 shadow-sm border border-white position-relative overflow-hidden"
                    >
                      <div className="row gy-4">
                        <div className="col-md-7">
                          <div className="d-flex gap-4">
                            <div className="item-info">
                              <h5 className="fw-700 mb-2 truncate-1">
                                {isService ? (
                                  <Link
                                    to={`/service/${data?.serviceSlug}/${hashids.safeEncodeHex(data)}`}
                                    className="text-heading hover-text-main transition-all"
                                  >
                                    {toTitleCase(data?.serviceName)}
                                  </Link>
                                ) : (
                                  <Link
                                    to={`/package/${data?.packageSlug}/${hashids.safeEncodeHex(data)}`}
                                    className="text-heading hover-text-main transition-all"
                                  >
                                    {toTitleCase(data?.packageName)}
                                  </Link>
                                )}
                              </h5>
                              <p className="text-main font-13 fw-600 mb-2">
                                {toTitleCase(data?.centre?.centreName)}
                              </p>
                              <div className="d-flex flex-wrap gap-2">
                                <span className="badge bg-light text-muted fw-500 rounded-pill px-3">
                                  {isService
                                    ? toTitleCase(data?.serviceCategory)
                                    : "Health Package"}
                                </span>
                                {data?.doctors?.[0]?.name && (
                                  <span className="badge bg-light text-muted fw-500 rounded-pill px-3">
                                    Dr. {toTitleCase(data.doctors[0].name)}
                                  </span>
                                )}
                              </div>
                            </div>
                          </div>
                        </div>

                        <div className="col-md-5">
                          <div className="appointment-selection-box p-3 rounded-3 bg-white-50 border">
                            <div className="row g-2">
                              <div className="col-5">
                                <label className="font-12 fw-600 text-muted mb-1 d-flex align-items-center gap-1">
                                  <FaCalendarAlt /> Date
                                </label>
                                <input
                                  type="date"
                                  className="form-control form-control-sm border-0 bg-transparent p-0 fw-600 text-heading"
                                  min={getTodayDate()}
                                  value={selectedDate || ""}
                                  onChange={(e) => {
                                    if (!isFutureOrToday(e.target.value)) {
                                      e.target.value = getTodayDate();
                                      alert("Please select a valid date.");
                                      return;
                                    }
                                    handleDateChange(itemId, e.target.value);
                                  }}
                                />
                              </div>
                              <div className="col-7 position-relative border-start ps-3">
                                <label className="font-12 fw-600 text-muted mb-1 d-flex align-items-center gap-1">
                                  <FaClock /> Slot
                                </label>
                                <select
                                  className="form-control form-control-sm border-0 bg-transparent p-0 fw-600 text-heading shadow-none"
                                  style={{
                                    appearance: "none",
                                    background: "none",
                                  }}
                                  value={appointmentData[itemId]?.time || ""}
                                  onChange={(e) =>
                                    handleTimeChange(itemId, e.target.value)
                                  }
                                  disabled={noSlotsForDay || !selectedDate}
                                >
                                  <option value="">
                                    {selectedDate ? "Time" : "Select Date"}
                                  </option>
                                  {filteredSlots.map((slotObj, idx) => (
                                    <option
                                      key={idx}
                                      value={
                                        isService
                                          ? `${slotObj.from} - ${slotObj.to}`
                                          : formatSlot(slotObj)
                                      }
                                    >
                                      {isService
                                        ? `${slotObj.from} - ${slotObj.to}`
                                        : formatSlot(slotObj)}
                                    </option>
                                  ))}
                                </select>
                              </div>
                            </div>
                            {noSlotsForDay && (
                              <div className="mt-2 text-danger font-11">
                                <FaInfoCircle /> No slots available for this
                                day.
                              </div>
                            )}
                          </div>
                        </div>
                      </div>

                      <div className="item-card-footer d-flex justify-content-between align-items-center mt-4 pt-3 border-top">
                        <div className="price-tag">
                          <span className="font-14 text-muted me-2">
                            Service Cost
                          </span>
                          <span className="font-22 fw-700 text-heading">
                            ₹{data?.totalPrice}
                          </span>
                        </div>
                        <button
                          className="btn btn-danger pill px-3 btn-sm d-flex align-items-center gap-2 shadow-sm fw-600"
                          onClick={() => handleRemove(item)}
                        >
                          <FaTrashAlt size={12} /> Remove
                        </button>
                      </div>
                    </div>
                  );
                })
              )}
            </div>

            <div className="cart-footer-actions d-flex justify-content-between align-items-center mt-5">
              <Link
                to={previousPage}
                className="btn btn-outline-light pill btn-lg px-4 d-flex align-items-center gap-2 text-heading"
              >
                <FaArrowLeft /> Book Other Service
              </Link>
            </div>
          </div>

          {/* Right Column: Order Summary */}
          <div className="col-lg-4">
            <div
              className="order-summary-sidebar sticky-top"
              style={{ top: "120px" }}
            >
              <div className="summary-card glass-effect p-4 rounded-4 shadow border border-white">
                <h4 className="fw-700 mb-4 pb-2 border-bottom">
                  Booking Summary
                </h4>

                <div className="summary-details d-flex flex-column gap-3 mb-4">
                  <div className="summary-row d-flex justify-content-between">
                    <span className="text-muted">Total Price</span>
                    <span className="fw-600">₹{totalPrice}</span>
                  </div>
                  {/* <div className="summary-row d-flex justify-content-between">
                        <span className="text-muted">Discount</span>
                        <span className="text-success fw-600">- ₹0</span>
                     </div> */}
                  {/* <div className="summary-row d-flex justify-content-between">
                        <span className="text-muted">Platform Fee</span>
                        <span className="text-main fw-600">Free</span>
                     </div> */}
                </div>

                <div className="total-row d-flex justify-content-between align-items-center pt-3 border-top mb-4">
                  <div className="total-label">
                    <h5 className="fw-700 mb-0">Payable Amount</h5>
                    <p className="text-muted font-12 mb-0">
                      Inclusive of all taxes
                    </p>
                  </div>
                  <h4 className="text-main fw-800 mb-0">₹{totalPrice}</h4>
                </div>

                <button
                  className="btn btn-main btn-lg pill w-100 py-3 fw-700 d-flex align-items-center justify-content-center gap-2 shadow-lg mb-3"
                  onClick={handleNextClick}
                >
                  Proceed to Details <FaArrowRight />
                </button>

                <p className="text-center text-muted font-13 mb-0">
                  Secure checkout powered by 4Ceps
                </p>
              </div>

              <div className="trust-card p-4 rounded-4 mt-4 bg-light border-0">
                <div className="d-flex align-items-center gap-3">
                  <div className="thumb text-main">
                    <FaCheckCircle size={30} />
                  </div>
                  <div className="content">
                    <h6 className="fw-700 mb-1">Easy Rescheduling</h6>
                    <p className="font-12 text-muted mb-0">
                      Cancel up to 2 hours before your appointment for full
                      flexibility.
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <UnifiedAuthModal
        isOpen={isAuthModalOpen}
        restrictToRole="patient"
        onClose={() => setIsAuthModalOpen(false)}
        onSuccess={(data) => {
          // If login success, proceed to checkout
          navigate("/cart-personal");
        }}
      />

      <style jsx>{`
        .glass-effect {
          background: rgba(255, 255, 255, 0.7);
          backdrop-filter: blur(10px);
          -webkit-backdrop-filter: blur(10px);
        }

        /* Progress Steps */
        .progress-line {
          height: 4px;
          background: #e9ecef;
        }

        .progress-step {
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 12px;
          z-index: 1;
        }

        .step-count {
          width: 45px;
          height: 45px;
          background: white;
          border: 4px solid #e9ecef;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          font-weight: 700;
          color: #adb5bd;
          transition: all 0.3s ease;
        }

        .progress-step.active .step-count {
          background: #a847f0; /* Branded Purple */
          border-color: #f3e8ff;
          color: white;
          transform: scale(1.15);
        }

        .step-label {
          font-weight: 600;
          font-size: 14px;
          color: #adb5bd;
        }

        .progress-step.active .step-label {
          color: #a847f0;
        }

        /* Cart Items */
        .cart-item-card {
          transition: all 0.3s ease;
        }

        .cart-item-card:hover {
          transform: translateX(5px);
          box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05) !important;
        }

        .item-badge-box {
          width: 70px;
          height: 70px;
          flex-shrink: 0;
        }

        .item-info h5 {
          display: -webkit-box;
          -webkit-line-clamp: 1;
          -webkit-box-orient: vertical;
          overflow: hidden;
        }

        .bg-white-50 {
          background: rgba(255, 255, 255, 0.5);
        }

        .font-11 {
          font-size: 11px;
        }
        .font-12 {
          font-size: 12px;
        }
        .font-13 {
          font-size: 13px;
        }

        .truncate-1 {
          display: -webkit-box;
          -webkit-line-clamp: 1;
          -webkit-box-orient: vertical;
          overflow: hidden;
        }

        .transition-all {
          transition: all 0.3s ease;
        }

        .order-summary-sidebar {
           z-index: 0;
        }

        @media (max-width: 991px) {
          .order-summary-sidebar {
            position: static !important;
            margin-top: 40px;
          }
        }
      `}</style>
    </div>
  );
};

export default Cart;
